```python
def switcher(fn):
    registry = {'default': fn}
    def register(case):
        def inner(f):
            registry[case] = f
            return f
        return inner
    def decorator(case, *args, **kwargs):
        return registry.get(case, registry['default'])(*args, **kwargs)
    decorator.register = register
    return decorator

@switcher
def calc(*args, **kwargs):
    raise ValueError('unknown operation')

@calc.register('add')
def _(a, b): return a + b

@calc.register('mul')
def _(a, b): return a * b

calc('add', 2, 3)   # 5
```
